/// <summary>
/// Runs the environment data setup tests from the web client and shows the results in the infolog.
/// </summary>
/// <remarks>
/// Open it with ?mi=SysClassRunner&cls=OLK_EnvironmentDataSetupTestJob. Each test method runs after its own setUp,
/// so the run does not depend on the Visual Studio test runner. The tests can also be run from the Test Explorer.
/// </remarks>
internal final class OLK_EnvironmentDataSetupTestJob
{
}

Method.Source:
public static void main(Args _args)
{
    SysDictClass    dictClass = new SysDictClass(classNum(OLK_EnvironmentDataSetupTest));
    SetEnumerator   methods   = dictClass.methods(true, false, false).getEnumerator();
    Set             testNames = new Set(Types::String);
    SetEnumerator   tests;
    int             passed;
    int             failed;

    while (methods.moveNext())
    {
        DictMethod dictMethod = methods.current();

        if (dictMethod.getAttribute(classStr(SysTestMethodAttribute)))
        {
            testNames.add(dictMethod.name());
        }
    }

    tests = testNames.getEnumerator();

    while (tests.moveNext())
    {
        if (OLK_EnvironmentDataSetupTestJob::runTest(tests.current()))
        {
            passed++;
        }
        else
        {
            failed++;
        }
    }

    if (failed)
    {
        error(strFmt('Environment data setup tests: %1 passed, %2 failed.', passed, failed));
    }
    else
    {
        info(strFmt('Environment data setup tests: %1 passed, %2 failed.', passed, failed));
    }
}

private static boolean runTest(MethodName _testName)
{
    OLK_EnvironmentDataSetupTest    test = new OLK_EnvironmentDataSetupTest();
    int                             infologStart = infologLine();
    str                             failure;

    try
    {
        test.setUp();
        new SysDictClass(classNum(OLK_EnvironmentDataSetupTest)).callObject(_testName, test);
        test.tearDown();
    }
    catch (Exception::CLRError)
    {
        failure = CLRInterop::getLastException().ToString();
    }
    catch
    {
        failure = infologLine() > infologStart ? infolog.text(infologLine()) : 'Unknown error';
    }

    if (failure)
    {
        error(strFmt('FAILED %1: %2', _testName, failure));
        return false;
    }

    info(strFmt('Passed %1', _testName));
    return true;
}
